#!/usr/bin/env python3
"""Семантический golden: examples/ должен выглядеть как валидный вывод /beerpowers:setup.

Отсутствие плейсхолдеров (check_placeholders.py) говорит лишь, что подстановка отработала.
Здесь проверяется то, на что опираются движок и `/beerpowers:doctor`: обязательные секции charter,
штамп версии, поля frontmatter ролей, инварианты `tools:` и agent-memory, схема отчёта
`reviewer`. Разъезд эталона с каноном ловится тут, а не на ревью глазами.

Проверки charter:
  * штамп `generated-by: beerpowers vX.Y.Z · mode: plugin-linked`, версия = plugin.json;
  * секции «Состав», «Intake-режим», «Доменные инварианты», «Правила работы», «Файлы памяти»;
  * рядом лежат `team-lead.md` и валидный `workspace.json` с версией плагина;
  * строка «Модели» под таблицей состава (с 1.11.0 — единственное место тира для ролей
    без собственного файла);
  * ни одного абсолютного пути к `reference/*` (с 1.12.0 их там быть не должно).

Проверки ролей:
  * frontmatter парсится, `name` совпадает с именем файла;
  * `model` — алиас тира (`opus`/`sonnet`/`haiku`), не `inherit` и не ID поколения;
  * `tools` без упразднённых (`MultiEdit`, `Computer`, голый `Task`);
  * роль ссылается на скилы → `Skill` заявлен в `tools` (иначе рантайм его не выдаст);
  * `memory` только из документированных значений + существует `agent-memory/<name>/MEMORY.md`;
  * header-note шаблона не перенесён; секции «Память роли» нет у роли без поля `memory`
    (правило памяти роли — в charter, а не в каждой роли);
  * `reviewer` несёт в схеме отчёта строку `## adversary:`;
  * каждая роль charter (кроме встроенных типов) имеет файл.

Проверки контракта движка (reference/workspace.md):
  * каждый engine-блок в charter, team-lead.md, агентах и памяти эталона побайтно равен
    одноимённому блоку шаблона — иначе эталон показывает не то, что сгенерирует setup,
    а update на нём не был бы пустым;
  * копии `.claude/bin/`, `.claude/hooks/` со шапкой `generated by` равны шаблону с версией
    плагина, копии `.claude/reference/` — файлу плагина под шапкой.
"""
import json
import pathlib
import re
import sys

PLUGIN_JSON = pathlib.Path("plugins/beerpowers/.claude-plugin/plugin.json")
EXAMPLES = pathlib.Path("examples")

STAMP = re.compile(
    r"generated-by: beerpowers v(\d+\.\d+\.\d+) · mode: (plugin-linked)"
)
CHARTER_SECTIONS = ["## Состав", "## Intake-режим", "## Доменные инварианты", "## Правила работы", "## Файлы памяти"]
MODELS_LINE = re.compile(r"^\*\*Модели:\*\*", re.M)
# Только путь от корня ФС или домашнего каталога: относительный `.claude/reference/X.md` —
# копия в проекте по контракту, её engine-блоки и называют.
ABS_REFERENCE = re.compile(r"(?<![\w.])(?:~/|/|[A-Za-z]:[\\/])[\w./\\-]*reference[\\/][\w-]+\.md")
MODEL_TIERS = {"opus", "sonnet", "haiku"}
RETIRED_TOOLS = {"MultiEdit", "Computer", "Task"}
MEMORY_VALUES = {"user", "project", "local"}
BUILTIN_TYPES = {"Explore", "Plan", "general-purpose"}
HEADER_NOTE = "Это generic-шаблон роли"
# Строка таблицы «Состав»: имена ролей и типов — латиница, в обратных кавычках или без.
CHARTER_ROW = re.compile(r"^\|\s*`?([A-Za-z][A-Za-z0-9_-]*)`?\s*\|\s*`?([A-Za-z][A-Za-z0-9_:-]*)`?\s*\|")
ROSTER_SECTION = re.compile(r"^## Состав\s*$(.*?)(?=^## |\Z)", re.M | re.S)


def parse_frontmatter(text):
    """Минимальный парсер: ключи верхнего уровня, значения-скаляры и inline-списки."""
    if not text.startswith("---\n"):
        return None
    end = text.find("\n---", 4)
    if end == -1:
        return None
    data = {}
    for line in text[4:end].splitlines():
        if not line or line.startswith((" ", "\t", "#")):
            continue
        key, sep, value = line.partition(":")
        if not sep:
            continue
        value = value.strip()
        if value.startswith("[") and value.endswith("]"):
            items = [v.strip().strip("\"'") for v in value[1:-1].split(",")]
            data[key.strip()] = [v for v in items if v]
        else:
            data[key.strip()] = value.strip("\"'")
    return data


def check_charter(path, plugin_version, problems):
    text = path.read_text(encoding="utf-8")

    stamp = STAMP.search(text)
    if not stamp:
        problems.append(f"{path}: нет штампа `generated-by: beerpowers vX.Y.Z · mode: …` — его читают hook дрейфа версий и update")
    elif stamp.group(1) != plugin_version:
        problems.append(
            f"{path}: штамп версии {stamp.group(1)}, а в plugin.json {plugin_version} — эталон отстал от плагина"
        )

    for section in CHARTER_SECTIONS:
        if section not in text:
            problems.append(f"{path}: нет обязательной секции «{section}» (её требует /beerpowers:doctor)")

    if not MODELS_LINE.search(text):
        problems.append(
            f"{path}: нет строки «**Модели:**» под таблицей состава — для ролей без своего файла это единственное место тира"
        )

    for match in ABS_REFERENCE.finditer(text):
        problems.append(
            f"{path}: абсолютный путь к reference — «{match.group(0)}»; с 1.12.0 роли ходят в скил по имени"
        )

    roles = {}
    roster = ROSTER_SECTION.search(text)
    if not roster:
        return roles
    for line in roster.group(1).splitlines():
        m = CHARTER_ROW.match(line)
        if m and m.group(1) not in {"Роль", "---"}:
            roles[m.group(1)] = m.group(2)
    return roles


def check_role(path, problems):
    text = path.read_text(encoding="utf-8")
    fm = parse_frontmatter(text)
    if fm is None:
        problems.append(f"{path}: frontmatter не парсится")
        return

    expected_name = path.stem
    if fm.get("name") != expected_name:
        problems.append(f"{path}: name={fm.get('name')!r}, а файл называется {expected_name!r}")

    model = fm.get("model")
    if model not in MODEL_TIERS:
        hint = "inherit привязал бы роль к модели сессии" if model == "inherit" else "тир пишем алиасом, не ID поколения"
        problems.append(f"{path}: model={model!r} — ожидается алиас тира {sorted(MODEL_TIERS)} ({hint})")

    tools = fm.get("tools") or []
    if not isinstance(tools, list) or not tools:
        problems.append(f"{path}: tools не список или пуст")
        tools = []
    for retired in RETIRED_TOOLS & set(tools):
        problems.append(f"{path}: в tools упразднённый {retired!r}")

    body = text.split("\n---", 1)[-1]
    if ("beerpowers:" in body or "Skill`" in body) and "Skill" not in tools:
        problems.append(
            f"{path}: роль ссылается на скилы, но `Skill` не заявлен в tools — рантайм его не выдаст"
        )

    memory = fm.get("memory")
    has_memory_section = "## Память роли" in text
    if memory is not None:
        if memory not in MEMORY_VALUES:
            problems.append(
                f"{path}: memory={memory!r} — документированы только {sorted(MEMORY_VALUES)}; отключение = отсутствие поля"
            )
        index = path.parent.parent / "agent-memory" / expected_name / "MEMORY.md"
        if not index.exists():
            problems.append(f"{path}: memory включена, но нет {index} — первый спавн роли шумит ошибкой чтения")
    elif has_memory_section:
        problems.append(
            f"{path}: секция «## Память роли» есть, а поля memory нет — роль учат вести память, которой рантайм ей не выдаст"
        )

    if HEADER_NOTE in text:
        problems.append(f"{path}: header-note шаблона перенесён в сгенерированное (setup 4.2 запрещает)")

    if expected_name.startswith("reviewer"):
        # Именно строка схемы, а не упоминание в прозе под ней («Строка `## adversary:` обязательна…»):
        # иначе удаление строки из шаблона отчёта пройдёт незамеченным.
        for required in ("## adversary:",):
            if not re.search(rf"^{re.escape(required)}", text, re.M):
                problems.append(
                    f"{path}: в схеме отчёта нет строки «{required}» — вердикт потеряет сигнал риска"
                )


TEMPLATES = pathlib.Path("plugins/beerpowers/templates")
REFERENCE = pathlib.Path("plugins/beerpowers/reference")
COPIED_REFERENCE = ["hooks.md", "tasks-layout.md", "worktrees.md", "git-flow.md"]
BLOCK = re.compile(
    r"<!-- beerpowers:engine ([a-z0-9-]+)(?: if=[^ ]+)? -->\n(.*?)<!-- /beerpowers:engine -->",
    re.S,
)
VERSION_TOKEN = "{{BEERPOWERS_VERSION}}"


def engine_blocks(text):
    return {m.group(1): m.group(2) for m in BLOCK.finditer(text)}


def template_for(project_file, root):
    rel = project_file.relative_to(root)
    parts = rel.parts
    if parts[:2] == (".claude", "team-charter.md"):
        return TEMPLATES / "charter" / "team-charter.md"
    if parts[:2] == (".claude", "team-lead.md"):
        return TEMPLATES / "charter" / "team-lead.md"
    if parts[:2] == (".claude", "agents"):
        return TEMPLATES / "roles" / parts[2]
    if parts[0] == "memory":
        return TEMPLATES / "memory" / pathlib.Path(*parts[1:])
    return None


def check_engine_contract(root, plugin_version, problems):
    team_lead = root / ".claude" / "team-lead.md"
    if not team_lead.exists():
        problems.append(f"{team_lead}: нет файла — charter 2.0 разрезан по читателю")
    workspace = root / ".claude" / "workspace.json"
    try:
        data = json.loads(workspace.read_text(encoding="utf-8"))
        if data.get("beerpowers") != plugin_version:
            problems.append(f"{workspace}: beerpowers={data.get('beerpowers')!r}, а плагин {plugin_version}")
    except FileNotFoundError:
        problems.append(f"{workspace}: нет файла — параметры путей и барьеры")
    except json.JSONDecodeError as error:
        problems.append(f"{workspace}: невалидный JSON — {error}")

    blocks_seen = 0
    candidates = [root / ".claude" / "team-charter.md", team_lead]
    candidates += sorted((root / ".claude" / "agents").glob("*.md"))
    candidates += sorted((root / "memory").rglob("*.md"))
    for project_file in candidates:
        if not project_file.exists():
            continue
        template = template_for(project_file, root)
        project_blocks = engine_blocks(project_file.read_text(encoding="utf-8"))
        if not project_blocks:
            continue
        if template is None or not template.exists():
            problems.append(f"{project_file}: engine-блоки есть, а шаблона нет")
            continue
        template_blocks = engine_blocks(template.read_text(encoding="utf-8"))
        for name, body in project_blocks.items():
            blocks_seen += 1
            if name not in template_blocks:
                problems.append(f"{project_file}: блока «{name}» нет в шаблоне {template}")
            elif body != template_blocks[name]:
                problems.append(f"{project_file}: блок «{name}» расходится с шаблоном {template}")
    if blocks_seen == 0:
        problems.append(f"{root}: ни одного engine-блока — эталон собран не по шаблонам 2.0")

    for kind in ("bin", "hooks"):
        base = root / ".claude" / kind
        if not base.is_dir():
            continue
        for copy in sorted(p for p in base.rglob("*") if p.is_file()):
            text = copy.read_text(encoding="utf-8")
            if "generated by beerpowers" not in "\n".join(text.splitlines()[:2]):
                continue
            template = TEMPLATES / kind / copy.relative_to(base)
            if not template.exists():
                problems.append(f"{copy}: копия без шаблона {template}")
            elif template.read_text(encoding="utf-8").replace(VERSION_TOKEN, plugin_version) != text:
                problems.append(f"{copy}: копия расходится с шаблоном {template}")
    for name in COPIED_REFERENCE:
        copy = root / ".claude" / "reference" / name
        if not copy.exists():
            continue
        head, _, body = copy.read_text(encoding="utf-8").partition("\n")
        # Шапку пишет setup, а не шаблон: сверка тела её не видит, и старое имя команды
        # в ней пережило бы переименование незамеченным.
        want = f"<!-- generated by beerpowers v{plugin_version} — не править: обновляет /beerpowers:update -->"
        if head != want:
            problems.append(f"{copy}: шапка «{head}», ждётся «{want}» (reference/workspace.md, «Шапка копии»)")
        if body != (REFERENCE / name).read_text(encoding="utf-8"):
            problems.append(f"{copy}: копия расходится с {REFERENCE / name}")


def main():
    problems = []
    plugin_version = json.loads(PLUGIN_JSON.read_text(encoding="utf-8"))["version"]
    charters = sorted(EXAMPLES.rglob(".claude/team-charter.md"))
    if not charters:
        print("Не найдено ни одного charter в examples/ — проверка деградировала", file=sys.stderr)
        return 1

    roles_checked = 0
    for charter in charters:
        roles = check_charter(charter, plugin_version, problems)
        agents_dir = charter.parent / "agents"
        for role, subagent_type in roles.items():
            if subagent_type in BUILTIN_TYPES:
                continue
            path = agents_dir / f"{subagent_type}.md"
            if not path.exists():
                problems.append(
                    f"{charter}: роль {role!r} заявлена как {subagent_type!r}, но {path} отсутствует"
                )
        for path in sorted(agents_dir.glob("*.md")):
            check_role(path, problems)
            roles_checked += 1

    for charter in charters:
        check_engine_contract(charter.parent.parent, plugin_version, problems)

    if problems:
        print("Golden-эталон разошёлся с каноном:")
        for p in problems:
            print(f"  - {p}")
        return 1

    print(
        f"OK: golden семантически валиден ({len(charters)} charter, {roles_checked} ролей, "
        f"версия {plugin_version})"
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
